def length_of_longest_substring(s: str) -> int:
    last = {}          # character -> last index seen
    left = 0           # window start
    best = 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1   # jump past the earlier copy
        last[ch] = right
        best = max(best, right - left + 1)
    return best
